/* Dataset interface used by every per-RQ example.
 *
 * Two implementations live behind this header:
 *
 *   src/dataset/smatable_dataset_npy.c      HOST    reads .npy via NPYLoader
 *                                                   (link only when
 *                                                    ODT_HOST_PLATFORM is set,
 *                                                    as it pulls in libc fs).
 *   src/dataset/smatable_dataset_baked.c    MCU     uses #include'd headers
 *                                                   generated by
 *                                                   tools/prep_smatable.py.
 *
 * The L1 equivalence test (tests/dataset_backend_equiv.c) is the only
 * translation unit that links BOTH backends; it discriminates them via the
 * symbols smatableDatasetOpen_npy and _baked. Normal builds pick exactly one
 * via the per-platform CMake glue under cmake/host and cmake/pico.
 *
 * Selection at compile time:
 *
 *   - Host:                                 NPY backend, paths come from env
 *                                           SMATABLE_DATA_DIR /
 *                                           SMATABLE_FOLD_SCHEME /
 *                                           SMATABLE_FOLD.
 *   - MCU:                                  baked backend, fold + scheme
 *                                           fixed at compile time via
 *                                           -DSMATABLE_FOLD=<k>
 *                                           and the corresponding .h files.
 */

#ifndef SMATABLE_DATASET_H
#define SMATABLE_DATASET_H

#include <stddef.h>
#include <stdint.h>

#define SMATABLE_DATASET_N_CLASSES 6

typedef struct smatable_dataset smatable_dataset_t;

/* Open the dataset for the current platform. On HOST this reads paths from
 * the environment; on MCU it returns a singleton over the baked tables.
 * Aborts (via PRINT_ERROR + exit) on failure — these errors are fatal-config
 * and not worth a recovery path. */
smatable_dataset_t *smatableDatasetOpen(void);
void                smatableDatasetClose(smatable_dataset_t *ds);

size_t smatableDatasetTrainCount(const smatable_dataset_t *ds);
size_t smatableDatasetTestCount (const smatable_dataset_t *ds);

/* outX must point to (n_channels * window_samples) floats.
 * outY receives a single int32 label.
 * Indices are local to each split (0..count-1). */
void smatableDatasetGetTrain(const smatable_dataset_t *ds, size_t i, float *outX, int32_t *outY);
void smatableDatasetGetTest (const smatable_dataset_t *ds, size_t i, float *outX, int32_t *outY);

size_t smatableDatasetNChannels    (const smatable_dataset_t *ds);
size_t smatableDatasetWindowSamples(const smatable_dataset_t *ds);
size_t smatableDatasetWindowFloats (const smatable_dataset_t *ds);
size_t smatableDatasetNClasses     (const smatable_dataset_t *ds);

#endif /* SMATABLE_DATASET_H */
